import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.C7GIOALF.js";const m=JSON.parse('{"title":"Classic Zombie Horde","description":"","frontmatter":{},"headers":[],"relativePath":"formats/horde/variants/classic.md","filePath":"formats/horde/variants/classic.md","lastUpdated":null}'),i={name:"formats/horde/variants/classic.md"};function s(n,e,d,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="classic-zombie-horde" tabindex="-1">Classic Zombie Horde <a class="header-anchor" href="#classic-zombie-horde" aria-label="Permalink to &quot;Classic Zombie Horde&quot;">​</a></h1><p><a href="./../">Horde versions</a> · <strong>Rules: Peter Knudson&#39;s September 2011 version</strong></p><h2 id="players-and-materials" tabindex="-1">Players and materials <a class="header-anchor" href="#players-and-materials" aria-label="Permalink to &quot;Players and materials&quot;">​</a></h2><p>One to four survivors cooperate against an automated Zombie deck. Each survivor uses a Commander deck; the original source also permits other Magic decks by agreement.</p><p>Build a 100-card Horde from approximately 60 token cards and 40 ordinary cards. Token cards are physically shuffled into the Horde library and are cast by the special procedure below. Choose cards that work without a human pilot. Use the <a href="./../sources/original-horde-magic-quiet-speculation.html#original-zombie-horde-deck">original Zombie decklist</a> if you want the published list.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Survivors</th><th style="text-align:right;">Shared life</th><th style="text-align:right;">Cards used from the shuffled Horde</th><th style="text-align:right;">Survivor setup turns</th></tr></thead><tbody><tr><td>1</td><td style="text-align:right;">20</td><td style="text-align:right;">45</td><td style="text-align:right;">3</td></tr><tr><td>2</td><td style="text-align:right;">40</td><td style="text-align:right;">60</td><td style="text-align:right;">3</td></tr><tr><td>3</td><td style="text-align:right;">60</td><td style="text-align:right;">75</td><td style="text-align:right;">3</td></tr><tr><td>4</td><td style="text-align:right;">80</td><td style="text-align:right;">100</td><td style="text-align:right;">3</td></tr></tbody></table><ol><li>Shuffle the 100-card Horde and randomly set aside enough cards to leave the number in the table.</li><li>The Horde begins with no cards in hand and no permanents.</li><li>Survivors shuffle their decks, prepare any commanders, draw their opening hands, and use normal mulligans.</li><li>Set the survivor team&#39;s shared life total to 20 per player.</li><li>Survivors take <strong>three shared turns</strong> before the Horde takes its first turn.</li></ol><h2 id="survivor-turns-and-resources" tabindex="-1">Survivor turns and resources <a class="header-anchor" href="#survivor-turns-and-resources" aria-label="Permalink to &quot;Survivor turns and resources&quot;">​</a></h2><p>Survivors take their phases and steps together. Each player draws from their own library, controls their own permanents, uses their own mana, and makes their own land play. They coordinate attacks and blocks.</p><p>Damage, life loss, and life gain affecting the survivors change their shared life total. The source&#39;s special shared-life setup replaces the usual individual Commander starting life.</p><h2 id="the-horde-s-turn" tabindex="-1">The Horde&#39;s turn <a class="header-anchor" href="#the-horde-s-turn" aria-label="Permalink to &quot;The Horde&#39;s turn&quot;">​</a></h2><p>After the setup turns, alternate a Horde turn with a shared survivor turn.</p><ol><li>Reveal the top card of the Horde library.</li><li>If it is a Zombie token, continue revealing.</li><li>Stop at the first non-token card, or when the library runs out.</li><li>Cast the revealed tokens, then cast the revealed non-token card last if there is one.</li><li>Proceed to combat. Horde Zombies have haste and must attack if able.</li></ol><p>The Horde&#39;s spells use the stack and players can respond, including countering them. Having infinite mana does not mean they bypass the stack.</p><p>The Horde attacks the survivor team. Survivors can block together for the team. Horde Zombies cannot block, so attacking the Horde does not require getting past its Zombies.</p><h2 id="horde-mana-choices-and-cards" tabindex="-1">Horde mana, choices, and cards <a class="header-anchor" href="#horde-mana-choices-and-cards" aria-label="Permalink to &quot;Horde mana, choices, and cards&quot;">​</a></h2><p>The Horde has unlimited mana for costs. Mana taxes such as Propaganda or Mana Leak do not stop it by requiring a payment it cannot afford. Non-mana costs still require whatever the card instructs.</p><p>Build the Horde to minimize choices. When an effect nevertheless requires a choice, make it as randomly as possible among legal options.</p><p>A permanent returned to the Horde&#39;s hand is cast again during its next main phase. The Horde starts with no hand; that does not erase the original rule for cards returned to its hand.</p><p>When a card interaction does not function in this automated format, the original source asks the group to choose a fair handling or cycle the problematic card. Agree the exact replacement procedure if using that escape hatch; the source does not define its cycling cost or timing.</p><h2 id="damaging-and-defeating-the-horde" tabindex="-1">Damaging and defeating the Horde <a class="header-anchor" href="#damaging-and-defeating-the-horde" aria-label="Permalink to &quot;Damaging and defeating the Horde&quot;">​</a></h2><p>The Horde has no life total. Each point of damage dealt to it puts one card from the top of its library into its graveyard. Survivors may attack it to reduce future waves.</p><p>The survivors win when <strong>the Horde library is empty and no Horde Zombies remain on the battlefield</strong>. An empty library alone is not victory while Zombies remain.</p><p>The Horde wins when the survivor team&#39;s shared life reaches <strong>zero or less</strong>.</p><h2 id="source-limitations-and-other-versions" tabindex="-1">Source limitations and other versions <a class="header-anchor" href="#source-limitations-and-other-versions" aria-label="Permalink to &quot;Source limitations and other versions&quot;">​</a></h2><p>The original article does not specify a complete set of special rules for poison, alternate-win cards, or every modern card type. It also does not have the follow-up&#39;s planeswalker attack procedure. Record additional decisions before using interactions that need them.</p><p>For a specific planeswalker procedure and the 2011 ban list, choose the <a href="./open-source.html">Open Source version</a>. For a different life system and rarity-based waves, choose <a href="./hordemagic.html">HordeMagic.com</a>.</p><p>Source: <a href="https://www.quietspeculation.com/2011/09/horde-magic-a-new-way-to-play-magic-and-survive-zombie-invasions/" target="_blank" rel="noreferrer">Horde Magic: A New Way to Play Magic and Survive Zombie Invasions</a>, Peter Knudson, September 29, 2011. <a href="./../sources/original-horde-magic-quiet-speculation.html">Archived notes and decklist</a>.</p>',29)])])}const p=t(i,[["render",s]]);export{m as __pageData,p as default};
